import React from 'react';
import { BrowserRouter, Routes, Route } from "react-router-dom";
import Layout from "./Layout";
import WeatherPage from "./WeatherPage";

function App(){
    return (
        <BrowserRouter>
            <Routes>
                <Route path="/" element={<Layout/>}>
                    <Route  index element={<WeatherPage />}/>
                </Route>
            </Routes>
        </BrowserRouter>
    );
}


export default App;
